#include "plugin_discovery.hpp"
#include "vst2_candidate.hpp"
static void vst2Tests(){
    for(int kind=0;kind<4;kind++){auto path=fs::path(L"build")/(L"vst2-fixture-"+std::to_wstring(kind)+L".dll");check(vst2Candidate(path),"VST2 export detected without executing DLL");Plugin plugin;std::string error;check(plugin.load(path,48000,error),error.c_str());check(plugin.info.category=="VST2"&&plugin.instrument()==(kind==1)&&plugin.acceptsNotes()==(kind==1),"VST2 instrument/FX classification");check(plugin.parameters().size()==1&&plugin.latency()==64,"VST2 parameters and latency");std::array<float,64>left{},right{},side{};left.fill(.4f);right.fill(.2f);side.fill(.4f);PluginNote notes[]={{8,60,0,1,true,0},{40,60,0,0,false,0}};if(kind==1)plugin.midiMessage(0xb0|(1<<8)|(127<<16));plugin.process(left.data(),right.data(),64,notes,2,2.5,123,true,nullptr,0,side.data(),side.data());for(int i=0;i<64;i++){float want=kind==1?(i>=8&&i<40?.15f:.05f):kind==2?.15f:kind==3?.25f:.2f;check(std::abs(left[i]-want)<1e-6,"VST2 stereo/mono/sidechain and sample-offset MIDI processing");}check(plugin.setParameter(0,.75),"VST2 parameter edit accepted");plugin.process(left.data(),right.data(),64,nullptr,0,0,120,false);auto state=plugin.state();Plugin clone;check(clone.load(path,48000,error),error.c_str());clone.restore(state);check(std::abs(clone.parameterValue(0)-.75)<1e-6,"VST2 chunk and parameter states restore");check(clone.prepare(44100),"VST2 sample-rate changes");left.fill(.4f);right.fill(.4f);std::vector<Point>curve={{0,.25f},{1,.25f}};clone.process(left.data(),right.data(),64,nullptr,0,0,120,true,&curve,0);check(std::isfinite(left[0])&&std::abs(clone.parameterValue(0)-.25)<1e-6,"VST2 automation and host time/sample rate");check(describePlugin(path).at("format")=="VST2","Isolated VST2 catalog descriptor");}
    check(!vst2Candidate(L"build/midi-fixture.vst3"),"Non-VST2 modules excluded from DLL search");auto plugins=findPlugins({L"build",L"build"});int count=0;for(auto&p:plugins)if(p.filename().wstring().find(L"vst2-fixture-")==0)count++;check(count==4,"VST2 discovery removes duplicate roots");Json favorite=cleanFavorites(Json::array({{{"path","C:/VST/Test.dll"},{"name","Test"}}}));check(favorite.size()==1,"VST2 supports Starred");
    auto base=fs::absolute(L"work/test-results/discovery");fs::create_directories(base/L"roaming/REAPER");fs::create_directories(base/L"VST & Synths");fs::create_directories(base/L"Effects");auto path=utf8((base/L"VST & Synths").wstring()),fx=utf8((base/L"Effects").wstring());std::ofstream(base/L"roaming/REAPER/reaper.ini")<<"[reaper]\nvstpath64="<<path<<";"<<fx<<"\nrecentproject=C:/unrelated\n";auto found=discoverPluginFolders(base/L"roaming",base/L"local",base/L"docs",false);check(found.size()==2,"DAW config path list imports existing plugin folders");auto xml=pluginPathsFromConfig(L"<Vst2CustomFolder Value=\""+(base/L"VST &amp; Synths").wstring()+L"\" />");check(xml.size()==1&&xml[0].find(L"VST & Synths")!=std::wstring::npos,"DAW XML paths decode entities");check(pluginPathsFromConfig(L"recent=C:\\Music\\session.als").empty(),"Project history never becomes a plugin directory");
    std::ofstream(L"work/test-results/vst2.json")<<Json({{"passed",true},{"fixtures",4},{"instrument_fx_mono_sidechain",true},{"sample_accurate_notes",true},{"midi_cc",true},{"state_chunks_and_parameters",true},{"automation",true},{"rate_change",true},{"pe_export_scan",true},{"folder_discovery",true},{"starred",true},{"third_party_vst2_tested",false}}).dump(2);
}
